# Using Vicuna Language Model in SwiftUI

Here are the main approaches to integrate Vicuna in a SwiftUI app:

## Option 1: Using llama.cpp (Local On-Device)

### Step 1: Set Up llama.cpp
```swift
// Add llama.cpp as a Swift Package
// Package.swift or via Xcode SPM:
// https://github.com/ggerganov/llama.cpp
```

### Step 2: Create a Model Manager
```swift
import Foundation

class VicunaModelManager: ObservableObject {
    @Published var output: String = ""
    @Published var isLoading: Bool = false

    private var modelPath: String = ""

    init() {
        // Path to your downloaded GGUF model file
        if let path = Bundle.main.path(forResource: "vicuna-7b-v1.5.Q4_K_M", ofType: "gguf") {
            modelPath = path
        }
    }

    func generate(prompt: String) async {
        await MainActor.run { isLoading = true }

        // Using LLM Swift package wrapper for llama.cpp
        let formattedPrompt = """
        A chat between a curious user and an artificial intelligence assistant.
        USER: \(prompt)
        ASSISTANT:
        """

        // Run inference (pseudocode - depends on your Swift wrapper)
        // let result = await llamaModel.generate(formattedPrompt)

        await MainActor.run {
            self.output = "Response here"
            self.isLoading = false
        }
    }
}
```

## Option 2: Using LLM Swift Package

### Step 1: Add Dependency
```swift
// In Package.swift
dependencies: [
    .package(url: "https://github.com/eastriverlee/LLM.swift", branch: "main")
]
```

### Step 2: Model Manager with LLM.swift
```swift
import LLM
import SwiftUI

class VicunaManager: ObservableObject {
    @Published var bot: LLM?
    @Published var isReady = false

    init() {
        Task {
            await loadModel()
        }
    }

    func loadModel() async {
        // Download or bundle the GGUF model
        guard let modelURL = Bundle.main.url(
            forResource: "vicuna-7b-v1.5.Q4_K_M",
            withExtension: "gguf"
        ) else { return }

        let systemPrompt = """
        A chat between a curious user and an AI assistant. \
        The assistant gives helpful, detailed answers.
        """

        let bot = await LLM(
            from: modelURL,
            template: .vicuna(systemPrompt)  // Uses Vicuna chat template
        )

        await MainActor.run {
            self.bot = bot
            self.isReady = true
        }
    }
}
```

## Option 3: Remote API (Recommended for Production)

### API Service
```swift
import Foundation

struct Message: Codable, Identifiable {
    let id = UUID()
    let role: String
    let content: String

    enum CodingKeys: String, CodingKey {
        case role, content
    }
}

struct ChatRequest: Codable {
    let model: String
    let messages: [Message]
    let temperature: Double
    let maxTokens: Int

    enum CodingKeys: String, CodingKey {
        case model, messages, temperature
        case maxTokens = "max_tokens"
    }
}

struct ChatResponse: Codable {
    struct Choice: Codable {
        struct Message: Codable {
            let content: String
        }
        let message: Message
    }
    let choices: [Choice]
}

class VicunaAPIService {
    private let baseURL = "http://your-server:8000/v1" // e.g., FastChat server
    private let apiKey = "your-api-key"

    func chat(messages: [Message]) async throws -> String {
        let url = URL(string: "\(baseURL)/chat/completions")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")

        let body = ChatRequest(
            model: "vicuna-7b-v1.5",
            messages: messages,
            temperature: 0.7,
            maxTokens: 512
        )

        request.httpBody = try JSONEncoder().encode(body)

        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(ChatResponse.self, from: data)

        return response.choices.first?.message.content ?? ""
    }
}
```

## SwiftUI Chat Interface

```swift
import SwiftUI

struct ChatView: View {
    @StateObject private var viewModel = ChatViewModel()
    @State private var userInput = ""
    @FocusState private var isInputFocused: Bool

    var body: some View {
        VStack(spacing: 0) {
            // Header
            Text("Vicuna Chat")
                .font(.headline)
                .padding()
                .frame(maxWidth: .infinity)
                .background(Color(.systemGray6))

            // Messages List
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(spacing: 12) {
                        ForEach(viewModel.messages) { message in
                            MessageBubble(message: message)
                                .id(message.id)
                        }

                        if viewModel.isLoading {
                            TypingIndicator()
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages.count) { _ in
                    scrollToBottom(proxy: proxy)
                }
            }

            // Input Area
            inputArea
        }
        .navigationBarTitleDisplayMode(.inline)
    }

    // MARK: - Input Area
    var inputArea: some View {
        HStack(spacing: 12) {
            TextField("Message Vicuna...", text: $userInput, axis: .vertical)
                .textFieldStyle(.plain)
                .padding(10)
                .background(Color(.systemGray6))
                .cornerRadius(20)
                .lineLimit(1...5)
                .focused($isInputFocused)

            Button {
                sendMessage()
            } label: {
                Image(systemName: "arrow.up.circle.fill")
                    .font(.system(size: 32))
                    .foregroundColor(
                        userInput.isEmpty || viewModel.isLoading
                            ? .gray : .blue
                    )
            }
            .disabled(userInput.isEmpty || viewModel.isLoading)
        }
        .padding(.horizontal)
        .padding(.vertical, 8)
        .background(Color(.systemBackground))
        .shadow(radius: 1)
    }

    private func sendMessage() {
        let text = userInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return }
        userInput = ""

        Task {
            await viewModel.sendMessage(text)
        }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        if let lastMessage = viewModel.messages.last {
            withAnimation {
                proxy.scrollTo(lastMessage.id, anchor: .bottom)
            }
        }
    }
}

// MARK: - Message Bubble
struct MessageBubble: View {
    let message: Message

    var isUser: Bool { message.role == "user" }

    var body: some View {
        HStack {
            if isUser { Spacer() }

            VStack(alignment: isUser ? .trailing : .leading, spacing: 4) {
                Text(isUser ? "You" : "Vicuna")
                    .font(.caption)
                    .foregroundColor(.secondary)

                Text(message.content)
                    .padding(12)
                    .background(isUser ? Color.blue : Color(.systemGray5))
                    .foregroundColor(isUser ? .white : .primary)
                    .cornerRadius(16)
            }

            if !isUser { Spacer() }
        }
    }
}

// MARK: - Typing Indicator
struct TypingIndicator: View {
    @State private var animate = false

    var body: some View {
        HStack {
            HStack(spacing: 4) {
                ForEach(0..<3) { index in
                    Circle()
                        .frame(width: 8, height: 8)
                        .foregroundColor(.gray)
                        .offset(y: animate ? -5 : 0)
                        .animation(
                            .easeInOut(duration: 0.5)
                                .repeatForever()
                                .delay(Double(index) * 0.15),
                            value: animate
                        )
                }
            }
            .padding(12)
            .background(Color(.systemGray5))
            .cornerRadius(16)

            Spacer()
        }
        .onAppear { animate = true }
    }
}
```

## ViewModel
```swift
@MainActor
class ChatViewModel: ObservableObject {
    @Published var messages: [Message] = []
    @Published var isLoading = false

    private let apiService = VicunaAPIService()

    // Add system message
    private var systemMessages: [Message] = [
        Message(
            role: "system",
            content: "You are a helpful AI assistant."
        )
    ]

    func sendMessage(_ content: String) async {
        // Add user message
        let userMessage = Message(role: "user", content: content)
        messages.append(userMessage)
        isLoading = true

        do {
            // Send conversation history
            let allMessages = systemMessages + messages
            let response = try await apiService.chat(messages: allMessages)

            let assistantMessage = Message(role: "assistant", content: response)
            messages.append(assistantMessage)
        } catch {
            let errorMessage = Message(
                role: "assistant",
                content: "Error: \(error.localizedDescription)"
            )
            messages.append(errorMessage)
        }

        isLoading = false
    }

    func clearChat() {
        messages.removeAll()
    }
}
```

## App Entry Point
```swift
@main
struct VicunaChatApp: App {
    var body: some Scene {
        WindowGroup {
            NavigationStack {
                ChatView()
            }
        }
    }
}
```

## Quick Comparison

| Approach | Pros | Cons |
|----------|------|------|
| **Local (llama.cpp)** | Private, offline | Large model size, slow on older devices |
| **LLM.swift** | Easy Swift integration | Limited customization |
| **Remote API** | Fast, scalable | Requires server, internet |

## Tips
- **Model Format**: Use **GGUF** format for on-device inference
- **Quantization**: Use `Q4_K_M` for balance of speed/quality
- **Vicuna Template**: Always format prompts with `USER:` / `ASSISTANT:` format
- **Memory**: 7B models need ~4GB RAM minimum on device

